method square (n: int) returns (r: int)
	requires 0 <= n;
	ensures r == n*n;
{
	var x: int;
	var i: int;

	r := 0;
	i := 0;
	x := 1;

	while (i < n)
	  invariant 0 <= i <= n // candidate
	  invariant r == i * i // candidate
	  invariant x == 2 * i + 1 // candidate
	  decreases n - i // candidate
	  invariant 0 <= i // candidate
	  invariant i <= n // candidate
	  invariant r == i*i // candidate
	{
		r := r + x;
		x := x + 2;
		i := i + 1;
	}
}

function F(n: nat): nat { if n <= 2 then n else F(n-1) + F(n-3)}

method calcF(n: nat) returns (res: nat)  
 ensures res == F(n) 
{
  var a, b, c := 0, 1, 2;
  var i := 0;
  while i < n
    decreases n - i // candidate
    invariant a == F(i) // candidate
    invariant b == F(i + 1) // candidate
    invariant c == F(i + 2) // candidate
    invariant 0 <= i // candidate
    invariant i <= n // candidate
   {
    a, b, c := b, c, a + c;        
    i := i + 1;
  }
  res := a;
}

method firste(a: array<char>) returns (c:int)
ensures -1 <= c < a.Length
ensures 0 <= c < a.Length ==> a[c] == 'e' && forall x :: 0 <= x < c ==> a[x] != 'e'
ensures c == -1 ==> forall x :: 0 <= x < a.Length ==> a[x] != 'e'
{
    var i:int := 0;
    while i < a.Length
      invariant 0 <= i // candidate
      invariant i <= a.Length // candidate
      invariant forall x :: 0 <= x < i ==> a[x] != 'e' // candidate
    {
        if a[i] == 'e' {
            return i;
        }
        i := i + 1;
    }
    return -1;
}

