method isPalindrome(s: array<char>) returns (result: bool)
    requires 1<= s.Length <= 200000
    ensures result <==> (forall i:: 0 <= i < s.Length / 2 ==> s[i] == s[s.Length - 1 - i])
{
    var length := s.Length;

    var i := 0;
    while i < length / 2
      invariant 0 <= i // candidate
      invariant i <= length / 2 // candidate
      invariant forall j:: 0 <= j < i ==> s[j] == s[length - 1 - j] // candidate
    {
        if s[i] != s[length - 1 - i]
        {
            return false;
        }

        i := i + 1;
    }

    return true;
}

method PairwiseAddition(a: array<int>) returns (result: array<int>)
    requires a != null
    requires a.Length % 2 == 0
    ensures result != null
    ensures result.Length == a.Length / 2
    ensures forall i :: 0 <= i < result.Length ==> result[i] == a[2*i] + a[2*i + 1]
{
    result := new int[a.Length / 2];
    var i := 0;
    while i < a.Length / 2
      invariant 0 <= i // candidate
      invariant i <= a.Length / 2 // candidate
      invariant result.Length == a.Length / 2 // candidate
      invariant forall j :: 0 <= j < i ==> result[j] == a[2*j] + a[2*j + 1] // candidate
    {
        result[i] := a[2*i] + a[2*i + 1];
        i := i + 1;
    }
}
